contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint deposit, uint minSumVal, uint amount, uint seed) public payable {
        require(deposit > minSumVal);
        require(amount < deposit);
        require(address(this).balance >= deposit);

        // setup: fresh contract configuration
        c.SetMinSum(minSumVal);
        c.Initialized();

        // fund the test contract's account on c via receive -> Deposit
        c.Deposit{value: deposit}();

        uint balBefore = c.balances(address(this));
        uint ethBefore = address(c).balance;
        // avoid reentrancy trouble: if amount is 0 just check balance is unchanged-ish
        bool reverted;
        if (seed > 0) {
            try c.Collect(amount) { reverted = false; }
            catch { reverted = true; }
        } else {
            c.Collect(amount);
            reverted = false;
        }

        assert(
            !reverted
            && c.balances(address(this)) == balBefore - amount
            && (amount == 0 || address(c).balance <= ethBefore)
        );
    }

    receive() external payable {}
}

