        c.SetMinSum(minSum);
        c.SetLogFile(address(this));
        c.Initialized();
        c.Deposit{value: depositAmount}();
        require(collectAmount <= c.balances(address(this)));
        bool reverted;
        try c.Collect(collectAmount) { reverted = false; } catch { reverted = true; }
        assert(c.MinSum() == minSum);
    }
    fallback() external payable {}
}
